          ]
        },
        {
          "proposicao": "O painel mímico ou monitor do sistema de lastro deve indicar conteúdo dos tanques, estado aberto/fechado de válvulas, tubulações e parâmetros das bombas; além disso, válvulas de tanques e de caixas de mar são descritas para falhar em fechado na perda de energia, reduzindo o risco de transferência indevida de lastro.",
          "trechos": [
            "Ea02fe041435f46b7:0:699",
            "Ea02fe041435f46b7:699:1397"
          ],
          "condicoes": [
            "arquitetura de controle e indicação do sistema de lastro",
            "cenário de perda de energia"
          ],
          "limites": [
            "trata-se de orientação técnica/recomendação e não de requisito brasileiro extraído de norma nacional",
            "o trecho não cobre todas as possíveis filosofias de falha ou instrumentação"
          ]
        }
      ]
    },
    {
      "id": "Ea6e024286e89f57a",
