          ]
        },
        {
          "proposicao": "O software de estabilidade é descrito como normalmente homologado por sociedade classificadora, mas a equipe marítima também deve ser capaz e competente para calcular a estabilidade sob todas as condições, inclusive sem energia.",
          "trechos": [
            "Ea6e024286e89f57a:696:1396"
          ],
          "condicoes": [
            "uso de software de estabilidade a bordo",
            "necessidade de operação também em contingência"
          ],
          "limites": [
            "a fonte não detalha critérios de competência, treinamento ou validação operacional",
            "a menção à homologação por classificador não equivale, por si só, a requisito regulatório brasileiro"
          ]
        }
      ]
